def count_tokens(text: str) -> int:
    """A rough token count (words and punctuation) for the simulator and for usage when an engine reports none."""
    return max(1, len(text.replace("\n", " ").split()))


def _last_user(messages: list[dict[str, Any]]) -> str:
    for m in reversed(messages):
        if m.get("role") == "user":
            c = m.get("content")
            return (
                c
                if isinstance(c, str)
                else " ".join(str(p.get("text", "")) for p in (c or []) if isinstance(p, dict))
            )
    return ""


