class _NoRedirect(urllib.request.HTTPRedirectHandler):
    def redirect_request(self, *a: Any, **k: Any) -> None:
        return None


def head(url: str) -> dict[str, str] | None:
    """The first response's headers (HF's size and sha256 headers live on the redirect, not on the CDN reply)."""
    opener = urllib.request.build_opener(_NoRedirect)
    req = urllib.request.Request(
        url, method="HEAD", headers={"User-Agent": "euron-localinference-catalog/0.1"}
    )
    try:
        resp = opener.open(req, timeout=30)
        return {k.lower(): v for k, v in resp.headers.items()}
    except urllib.error.HTTPError as e:
        if e.code in (301, 302, 303, 307, 308):
            return {k.lower(): v for k, v in e.headers.items()}
        print(f"  ! {url} -> HTTP {e.code}", file=sys.stderr)
    except OSError as e:
        print(f"  ! {url} -> {e}", file=sys.stderr)
    return None


