    backend = "external"

    def __init__(self, base_url: str, upstream_model: str, api_key: str | None = None) -> None:
        self.pid: int | None = None
        self.started_at = time.time()
        self.base_url = base_url.rstrip("/")
        self.upstream_model = upstream_model
        self._headers = {"Authorization": f"Bearer {api_key}"} if api_key else {}
        self._client = httpx.AsyncClient(timeout=httpx.Timeout(10, read=600))
        self._alive = True

    @property
    def alive(self) -> bool:
        return self._alive

    def diagnostics(self) -> str:
        return f"external engine at {self.base_url}"

    async def _post(self, path: str, body: dict[str, Any]) -> dict[str, Any]:
        try:
            r = await self._client.post(
                f"{self.base_url}{path}", json={**body, "model": self.upstream_model}, headers=self._headers
            )
        except httpx.HTTPError as exc:
            raise EngineError(
                503,
                f"cannot reach the external engine at {self.base_url}: {exc.__class__.__name__}",
                "engine_unreachable",
            ) from exc
        if r.status_code >= 400:
            raise EngineError(
                r.status_code if r.status_code < 500 else 502,
                f"the external engine answered HTTP {r.status_code}",
                "engine_rejected",
            )
        out: dict[str, Any] = r.json()
        return out

    async def chat(self, body: dict[str, Any]) -> dict[str, Any]:
        return await self._post("/chat/completions", {**body, "stream": False})

    async def chat_stream(self, body: dict[str, Any]) -> AsyncIterator[dict[str, Any]]:
        payload = {
            **body,
            "model": self.upstream_model,
            "stream": True,
            "stream_options": {"include_usage": True},
        }
        try:
            async with self._client.stream(
                "POST", f"{self.base_url}/chat/completions", json=payload, headers=self._headers
            ) as r:
                if r.status_code >= 400:
                    await r.aread()
                    raise EngineError(
                        r.status_code if r.status_code < 500 else 502,
                        f"the external engine answered HTTP {r.status_code}",
                        "engine_rejected",
                    )
