function applyPreset(p: Preset) {
  setPreset(p);
  setType(p.type);
  setQueue(p.queue);
  setPayload(prettyJson(p.payload));
  setRetry({ ...DEFAULT_RETRY, ...p.retry });
  setTimeoutS((p.timeout_ms ?? 60_000) / 1000);
  setLast(null);
}

const submit = useMutation({
  mutationFn: async () => {
    if ("error" in parsed) throw new Error(parsed.error);
    const base: EnqueueBody = {
      queue, type: type.trim(), payload: parsed.value, priority, delay_ms: Math.round(delay * 1000),
      timeout_ms: Math.round(timeoutS * 1000), retry, ...(idem.trim() && count === 1 ? { idempotency_key: idem.trim() } : {}),
    };
    let result: EnqueueResult | null = null;
    for (let i = 0; i < count; i++) result = await api.enqueue(base);
    return result!;
  },
  onSuccess: (r) => {
    setLast(r);
    toast("success", count > 1 ? `Enqueued ${count} jobs` : r.duplicate ? "Duplicate: returned the existing job" : "Job enqueued");
